       ref: interview:domains/authoring/interview.jsonl#L24
     status: confirmed
   decide:
-    description: Decide a requested decision.
+    description: Decide a requested decision. The owner decides; an agent may settle
+      it on the owner's behalf when the owner has said so in chat, quoting the owner's
+      words in owner_words.
     actor:
     - owner
     target: DecisionRequest
     params:
       choice:
         type: string
-    requires: human
+      owner_words:
+        type: string
+        optional: true
     records_decision: true
     effects:
     - set:
         target.choice: params.choice
     source:
-      kind: record
-      ref: records:docs/adr/0032-domain-knowledge-as-git-and-github.md#L38-L63
